/-- A support that contains all of the near-litters that transitively constrain something in `S`. -/
def constrainsNearLitters (S : Support β) : Support β :=
  ⟨.empty, .ofSet _ (reflTransGen_constrains_small Sᴺ Sᴺ.coe_small)⟩

